            new ParamDef(P.B8Freq, "B8Freq", "B8 freq", 0, 10000, 9847, MapKind.Freq, a: 20, b: 20000, group: "Band 8", description: "Band 8 frequency: centre, shelf midpoint or cutoff", how: "Sets band 8's frequency, from 20 Hz to 20 kHz: its centre, shelf midpoint or cutoff.", sound: "Moving it chooses which part of the sound the band shapes, from deep bass to air."),
            new ParamDef(P.B8Gain, "B8Gain", "B8 gain", 0, 480, 240, MapKind.Db, a: -24, b: 24, group: "Band 8", description: "Band 8 gain in 0.1 dB steps (bells and shelves)", how: "Sets band 8's boost or cut, from -24 to +24 dB, for bells and shelves.", sound: "Positive values bring that region forward; negative values pull it back."),
            new ParamDef(P.B8Q, "B8Q", "B8 Q", 0, 2000, 686, MapKind.Exp, a: 0.1, b: 30, digits: 2, group: "Band 8", description: "Band 8 Q: bell and notch width, shelf and cut resonance (0.71 is flat)", how: "Sets band 8's width, from 0.1 to 30; higher values are narrower (and make shelves and cuts resonate).", sound: "Narrow values shape one tone or resonance; wide values change the broad tone smoothly."),
            new ParamDef(P.B8Slope, "B8Slope", "B8 slope", 0, 2, 0, MapKind.Enum, names: new[] { "12 dB/oct", "24 dB/oct", "48 dB/oct" }, group: "Band 8", description: "Band 8 slope (low and high cut)", how: "Sets the steepness of band 8 when it is a low or high cut: 12, 24 or 48 dB per octave.", sound: "Steeper slopes remove the cut region more completely; gentler ones blend in more naturally."),
            new ParamDef(P.Output, "Output", "Output", 0, 480, 240, MapKind.Db, a: -24, b: 24, group: "Output", description: "Output gain in 0.1 dB steps", how: "Sets the output gain, from -24 to +24 dB.", sound: "It makes the whole sound louder or quieter after the EQ, without changing the tone."),
            new ParamDef(P.Mode, "Mode", "Mode", 0, 1, 0, MapKind.Enum, names: new[] { "Parametric", "Graphic" }, group: "Mode", description: "Parametric: the eight bands above. Graphic: 31 constant-Q bands at the ISO third-octave centres, 20 Hz – 20 kHz, set by the G sliders; the response passes through every slider (the bands' overlap compensated), and the parametric bands rest", how: "Chooses Parametric, with eight bands, or Graphic, with 31 third-octave sliders.", sound: "Parametric suits precise surgery; Graphic suits quick tonal shaping across the whole spectrum."),
