            new ParamDef(P.B1Chan, "B1Chan", "B1 channel", 0, 4, 0, MapKind.Enum, names: new[] { "Stereo", "Left", "Right", "Mid", "Side" }, group: "Channel and dynamics 1", description: "Band 1: which channel it works on. Stereo: both (as v1); Left or Right: that one alone; Mid or Side: the mid (L+R)/2 or the side (L−R)/2 alone, the other untouched (mid/side encoded and decoded around the band)", how: "Chooses which channel band 1 works on: both, left, right, mid or side.", sound: "Mid or side lets you shape the centre or the width alone, for example brightening only the sides."),
            new ParamDef(P.B1Shape, "B1Shape", "B1 shape", 0, 4, 0, MapKind.Enum, names: new[] { "Standard", "Proportional Q", "Baxandall", "Vintage", "All-pass" }, group: "Channel and dynamics 1", description: "Band 1: Standard: the type as it is (as v1). Proportional Q: a bell narrows as its gain grows (Q × 10^(|gain|/40): about twice as narrow for every 12 dB). Baxandall: a shelf becomes first order, 6 dB/oct, the gentle tone-control curve (Q unused). Vintage: a shelf gets its complementary dip, Pultec-style: a bell of half its gain the other way, Q 1, an octave above a low shelf or below a high shelf. All-pass: whatever the type, the band only turns the phase (second order at its frequency, Q its width)", how: "Chooses band 1's character: Standard, Proportional Q, Baxandall, Vintage or All-pass.", sound: "Proportional Q narrows with gain for a more musical feel, Baxandall makes a gentle tone-control tilt and All-pass shifts phase without changing tone."),
            new ParamDef(P.B1Dyn, "B1Dyn", "B1 dynamic", 0, 2, 0, MapKind.Enum, names: new[] { "Off", "Down", "Up" }, group: "Channel and dynamics 1", description: "Band 1 dynamic EQ (bells and shelves): Down: above the threshold the band's gain moves down (compresses what it hears), Up: it moves up; by the ratio, at most Range. The detector hears the band's own shape (a band-pass for a bell, low-pass for a low shelf, high-pass for a high shelf). Off: static (as v1)", how: "Makes band 1 dynamic: Down turns its gain down when its detector gets loud, Up turns it up.", sound: "The band only acts when the sound in that region needs it, such as taming harshness only on loud notes."),
            new ParamDef(P.B1Thresh, "B1Thresh", "B1 threshold", 0, 600, 300, MapKind.Linear, a: -60, b: 0, unit: "dB", digits: 1, group: "Channel and dynamics 1", description: "Band 1 dynamic: the level the band's detector must pass before its gain moves (dBFS, the envelope of what it hears)", how: "Sets the level, from -60 to 0 dB, that band 1's detector must pass before its gain moves.", sound: "Lower values make the dynamic band act more often."),
            new ParamDef(P.B1Ratio, "B1Ratio", "B1 ratio", 0, 1000, 463, MapKind.Ratio, a: 1, b: 20, flag: true, group: "Channel and dynamics 1", description: "Band 1 dynamic: the gain moves by 1 − 1/ratio dB for each dB over the threshold (∞: all of it)", how: "Sets how strongly band 1's gain follows the level above its threshold, from 1:1 to infinity.", sound: "Higher ratios make the dynamic action firmer and more decisive."),
            new ParamDef(P.B1Knee, "B1Knee", "B1 knee", 0, 240, 60, MapKind.Linear, a: 0, b: 24, unit: "dB", digits: 1, group: "Channel and dynamics 1", description: "Band 1 dynamic: width of the soft knee around the threshold", how: "Sets how gradually band 1's dynamic action starts around the threshold, from 0 to 24 dB.", sound: "Wider knees are smoother and less noticeable."),
            new ParamDef(P.B1Range, "B1Range", "B1 range", 0, 240, 60, MapKind.Linear, a: 0, b: 24, unit: "dB", digits: 1, group: "Channel and dynamics 1", description: "Band 1 dynamic: the most the gain moves from its setting", how: "Limits how far band 1's gain can move from its setting, from 0 to 24 dB.", sound: "A small range keeps the dynamic effect subtle; a large one lets it act strongly."),
            new ParamDef(P.B1Attack, "B1Attack", "B1 attack", 0, 1000, 639, MapKind.Time, a: 5e-05, b: 0.2, group: "Channel and dynamics 1", description: "Band 1 dynamic: time to 63 % of a gain change", how: "Sets how fast band 1's gain reacts, from 0.05 ms to 200 ms.", sound: "Fast attacks catch short peaks; slow ones let them through first."),
            new ParamDef(P.B1Release, "B1Release", "B1 release", 0, 1000, 532, MapKind.Time, a: 0.005, b: 3, group: "Channel and dynamics 1", description: "Band 1 dynamic: time back to 37 % of a gain change", how: "Sets how fast band 1's gain returns, from 5 ms to 3 s.", sound: "Short releases sound lively; long ones sound smooth and steady."),
            new ParamDef(P.B1Detect, "B1Detect", "B1 detector", 0, 1, 0, MapKind.Enum, names: new[] { "Band", "Sidechain" }, group: "Channel and dynamics 1", description: "Band 1 dynamic: Band: the detector hears the band's own input; Sidechain: the machine's second input (connect a machine to it), through the same shape and channel", how: "Chooses whether band 1's detector hears its own input or the machine on the second input.", sound: "Sidechain lets another sound, such as a vocal, control the band, for example to clear space in a pad."),
            new ParamDef(P.B2Chan, "B2Chan", "B2 channel", 0, 4, 0, MapKind.Enum, names: new[] { "Stereo", "Left", "Right", "Mid", "Side" }, group: "Channel and dynamics 2", description: "Band 2: which channel it works on. Stereo: both (as v1); Left or Right: that one alone; Mid or Side: the mid (L+R)/2 or the side (L−R)/2 alone, the other untouched (mid/side encoded and decoded around the band)", how: "Chooses which channel band 2 works on: both, left, right, mid or side.", sound: "Mid or side lets you shape the centre or the width alone, for example brightening only the sides."),
            new ParamDef(P.B2Shape, "B2Shape", "B2 shape", 0, 4, 0, MapKind.Enum, names: new[] { "Standard", "Proportional Q", "Baxandall", "Vintage", "All-pass" }, group: "Channel and dynamics 2", description: "Band 2: Standard: the type as it is (as v1). Proportional Q: a bell narrows as its gain grows (Q × 10^(|gain|/40): about twice as narrow for every 12 dB). Baxandall: a shelf becomes first order, 6 dB/oct, the gentle tone-control curve (Q unused). Vintage: a shelf gets its complementary dip, Pultec-style: a bell of half its gain the other way, Q 1, an octave above a low shelf or below a high shelf. All-pass: whatever the type, the band only turns the phase (second order at its frequency, Q its width)", how: "Chooses band 2's character: Standard, Proportional Q, Baxandall, Vintage or All-pass.", sound: "Proportional Q narrows with gain for a more musical feel, Baxandall makes a gentle tone-control tilt and All-pass shifts phase without changing tone."),
            new ParamDef(P.B2Dyn, "B2Dyn", "B2 dynamic", 0, 2, 0, MapKind.Enum, names: new[] { "Off", "Down", "Up" }, group: "Channel and dynamics 2", description: "Band 2 dynamic EQ (bells and shelves): Down: above the threshold the band's gain moves down (compresses what it hears), Up: it moves up; by the ratio, at most Range. The detector hears the band's own shape (a band-pass for a bell, low-pass for a low shelf, high-pass for a high shelf). Off: static (as v1)", how: "Makes band 2 dynamic: Down turns its gain down when its detector gets loud, Up turns it up.", sound: "The band only acts when the sound in that region needs it, such as taming harshness only on loud notes."),
            new ParamDef(P.B2Thresh, "B2Thresh", "B2 threshold", 0, 600, 300, MapKind.Linear, a: -60, b: 0, unit: "dB", digits: 1, group: "Channel and dynamics 2", description: "Band 2 dynamic: the level the band's detector must pass before its gain moves (dBFS, the envelope of what it hears)", how: "Sets the level, from -60 to 0 dB, that band 2's detector must pass before its gain moves.", sound: "Lower values make the dynamic band act more often."),
            new ParamDef(P.B2Ratio, "B2Ratio", "B2 ratio", 0, 1000, 463, MapKind.Ratio, a: 1, b: 20, flag: true, group: "Channel and dynamics 2", description: "Band 2 dynamic: the gain moves by 1 − 1/ratio dB for each dB over the threshold (∞: all of it)", how: "Sets how strongly band 2's gain follows the level above its threshold, from 1:1 to infinity.", sound: "Higher ratios make the dynamic action firmer and more decisive."),
            new ParamDef(P.B2Knee, "B2Knee", "B2 knee", 0, 240, 60, MapKind.Linear, a: 0, b: 24, unit: "dB", digits: 1, group: "Channel and dynamics 2", description: "Band 2 dynamic: width of the soft knee around the threshold", how: "Sets how gradually band 2's dynamic action starts around the threshold, from 0 to 24 dB.", sound: "Wider knees are smoother and less noticeable."),
            new ParamDef(P.B2Range, "B2Range", "B2 range", 0, 240, 60, MapKind.Linear, a: 0, b: 24, unit: "dB", digits: 1, group: "Channel and dynamics 2", description: "Band 2 dynamic: the most the gain moves from its setting", how: "Limits how far band 2's gain can move from its setting, from 0 to 24 dB.", sound: "A small range keeps the dynamic effect subtle; a large one lets it act strongly."),
            new ParamDef(P.B2Attack, "B2Attack", "B2 attack", 0, 1000, 639, MapKind.Time, a: 5e-05, b: 0.2, group: "Channel and dynamics 2", description: "Band 2 dynamic: time to 63 % of a gain change", how: "Sets how fast band 2's gain reacts, from 0.05 ms to 200 ms.", sound: "Fast attacks catch short peaks; slow ones let them through first."),
