            new ParamDef(P.B8Shape, "B8Shape", "B8 shape", 0, 4, 0, MapKind.Enum, names: new[] { "Standard", "Proportional Q", "Baxandall", "Vintage", "All-pass" }, group: "Channel and dynamics 8", description: "Band 8: Standard: the type as it is (as v1). Proportional Q: a bell narrows as its gain grows (Q × 10^(|gain|/40): about twice as narrow for every 12 dB). Baxandall: a shelf becomes first order, 6 dB/oct, the gentle tone-control curve (Q unused). Vintage: a shelf gets its complementary dip, Pultec-style: a bell of half its gain the other way, Q 1, an octave above a low shelf or below a high shelf. All-pass: whatever the type, the band only turns the phase (second order at its frequency, Q its width)", how: "Chooses band 8's character: Standard, Proportional Q, Baxandall, Vintage or All-pass.", sound: "Proportional Q narrows with gain for a more musical feel, Baxandall makes a gentle tone-control tilt and All-pass shifts phase without changing tone."),
            new ParamDef(P.B8Dyn, "B8Dyn", "B8 dynamic", 0, 2, 0, MapKind.Enum, names: new[] { "Off", "Down", "Up" }, group: "Channel and dynamics 8", description: "Band 8 dynamic EQ (bells and shelves): Down: above the threshold the band's gain moves down (compresses what it hears), Up: it moves up; by the ratio, at most Range. The detector hears the band's own shape (a band-pass for a bell, low-pass for a low shelf, high-pass for a high shelf). Off: static (as v1)", how: "Makes band 8 dynamic: Down turns its gain down when its detector gets loud, Up turns it up.", sound: "The band only acts when the sound in that region needs it, such as taming harshness only on loud notes."),
            new ParamDef(P.B8Thresh, "B8Thresh", "B8 threshold", 0, 600, 300, MapKind.Linear, a: -60, b: 0, unit: "dB", digits: 1, group: "Channel and dynamics 8", description: "Band 8 dynamic: the level the band's detector must pass before its gain moves (dBFS, the envelope of what it hears)", how: "Sets the level, from -60 to 0 dB, that band 8's detector must pass before its gain moves.", sound: "Lower values make the dynamic band act more often."),
            new ParamDef(P.B8Ratio, "B8Ratio", "B8 ratio", 0, 1000, 463, MapKind.Ratio, a: 1, b: 20, flag: true, group: "Channel and dynamics 8", description: "Band 8 dynamic: the gain moves by 1 − 1/ratio dB for each dB over the threshold (∞: all of it)", how: "Sets how strongly band 8's gain follows the level above its threshold, from 1:1 to infinity.", sound: "Higher ratios make the dynamic action firmer and more decisive."),
            new ParamDef(P.B8Knee, "B8Knee", "B8 knee", 0, 240, 60, MapKind.Linear, a: 0, b: 24, unit: "dB", digits: 1, group: "Channel and dynamics 8", description: "Band 8 dynamic: width of the soft knee around the threshold", how: "Sets how gradually band 8's dynamic action starts around the threshold, from 0 to 24 dB.", sound: "Wider knees are smoother and less noticeable."),
            new ParamDef(P.B8Range, "B8Range", "B8 range", 0, 240, 60, MapKind.Linear, a: 0, b: 24, unit: "dB", digits: 1, group: "Channel and dynamics 8", description: "Band 8 dynamic: the most the gain moves from its setting", how: "Limits how far band 8's gain can move from its setting, from 0 to 24 dB.", sound: "A small range keeps the dynamic effect subtle; a large one lets it act strongly."),
            new ParamDef(P.B8Attack, "B8Attack", "B8 attack", 0, 1000, 639, MapKind.Time, a: 5e-05, b: 0.2, group: "Channel and dynamics 8", description: "Band 8 dynamic: time to 63 % of a gain change", how: "Sets how fast band 8's gain reacts, from 0.05 ms to 200 ms.", sound: "Fast attacks catch short peaks; slow ones let them through first."),
            new ParamDef(P.B8Release, "B8Release", "B8 release", 0, 1000, 532, MapKind.Time, a: 0.005, b: 3, group: "Channel and dynamics 8", description: "Band 8 dynamic: time back to 37 % of a gain change", how: "Sets how fast band 8's gain returns, from 5 ms to 3 s.", sound: "Short releases sound lively; long ones sound smooth and steady."),
            new ParamDef(P.B8Detect, "B8Detect", "B8 detector", 0, 1, 0, MapKind.Enum, names: new[] { "Band", "Sidechain" }, group: "Channel and dynamics 8", description: "Band 8 dynamic: Band: the detector hears the band's own input; Sidechain: the machine's second input (connect a machine to it), through the same shape and channel", how: "Chooses whether band 8's detector hears its own input or the machine on the second input.", sound: "Sidechain lets another sound, such as a vocal, control the band, for example to clear space in a pad."),
            new ParamDef(P.Delta, "Delta", "Delta", 0, 1, 0, MapKind.Switch, group: "Monitor", description: "Hear only what the EQ changes: the output minus the input, before Output (zero latency, nothing to delay), gliding over 10 ms. Off for rendering", how: "Plays only the difference between the output and the input.", sound: "You hear only what the EQ adds or removes."),
            new ParamDef(P.Phase, "Phase", "Phase", 0, 1, 0, MapKind.Enum, names: new[] { "Minimum", "Linear" }, group: "Linear phase", description: "Minimum: the bands as always, zero latency. Linear: one FIR from the bands' zero-phase magnitude (same dB at every frequency from 30 Hz, no phase turning, constant delay of 4095 + 512 samples at 44.1/48 kHz, reported to the host); Parametric mode only; dynamic bands are static in it; the Curve layer applies; a very narrow band at a low frequency is limited in Q (the editor says so)", how: "Chooses minimum phase with no latency, or linear phase with a constant delay of about 4600 samples (about 100 ms).", sound: "Linear phase keeps the timing of all frequencies intact, which sounds cleaner on big boosts and in mastering."),
            new ParamDef(P.Curve1, "Curve1", "Curve 1", 0, 480, 240, MapKind.Db, a: -24, b: 24, group: "Linear phase", description: "Curve layer point 1 of 32 (log-spaced 20 Hz to 20 kHz, joined by a smooth curve), in dB, added to the bands before the linear-phase design (a match curve; Linear phase only)", how: "Sets point 1 of 32 on a smooth correction curve from 20 Hz to 20 kHz, from -24 to +24 dB (linear phase only).", sound: "It adds a detailed overall tone correction, such as a matching curve, on top of the bands."),
